// generar_305_menos_ruido_examenes_y_visitas.js
// CHIQUI Entre Señales — Menos ruido visual en Documentos de examen y Visitas
//
// Dos ajustes para que la información importante resalte:
//
// 1. DOCUMENTOS DE EXAMEN: se quita la píldora "Hace X días" que
//    mostraba cuándo fue el último examen en el encabezado. Era ruido;
//    la fecha ya está en cada documento.
//
// 2. VISITAS VETERINARIAS: el historial de visitas pasadas ahora se
//    muestra PLEGADO — solo aparece la visita más reciente, y el resto
//    queda tras un botón "Ver historial completo (N)". Así, al abrir la
//    sección, lo que se ve es lo relevante: las próximas visitas y la
//    última que pasó. El historial completo se despliega solo si se
//    necesita (botón "Ver menos" para volver a plegar).
//
// No hay SQL.
//
// Uso:
//   node generar_305_menos_ruido_examenes_y_visitas.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/prevencion/page.tsx",
    base64: ""
  },
  {
    ruta: "components/VisitasVeterinarias.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
